<p>Quẻ Khôn chỉ thời cuộc thiên về nhu thuận bình lặng, không hợp với những đổi thay sóng gió hay bạo lực. Thời vận của sự bao dung, của tôn giáo, chiêm bốc, kẻ tu hành ẩn dật. Mọi mưu đồ trái với lẽ trên đều thất bại. Vì vậy nên yên tâm nghề nghiệp cứ lắng nghe ý kiến người trên, làm theo mọi người, không nên đặt mục đích quá cao mà thất bại. Tài vận chưa đến, kinh doanh mức cũ hoặc cùng hợp tác với nhiều người. Nên làm các công việc từ thiện. Xuất hành đi xa bất lợi. Kiện tụng khó xong. Thi cử khó đạt như ý. Tình yêu lắm mối nhưng không thuận lợi. Hôn nhân do dự, khó tính. Người có quẻ này nếu sinh vào tháng mười là đắc cách, gặp thời của những bậc phú quý danh gia. Sinh không đúng tháng, không đúng mùa nhưng là mệnh nữ thì vẫn tốt, nhu thuận, hiền hoà, gia đình êm ấm. Số có nhiều ruộng đất, tài sản.</p>

