<p><strong>Đoán quẻ 2:</strong> Điềm báo trước cơ nghiệp suy vi. Xét về mọi mặt, hãy rút lui và giữ nguyên tình trạng đó. Hãy cực kỳ cẩn thận trong lời nói, hành động và cách thức xử lý công việc, và bạn có thể an toàn cũng như vững vàng. Bạn có thể bị vu khống bởi những kẻ nhỏ mọn, bị lôi kéo vào những phiền phức bởi cấp dưới, và có thể bị mất của cải hay tiền bạc.</p>
