<p><strong>Đoán quẻ 2:</strong> Bởi các gánh nặng và trách nhiệm quá sức nặng nề, nên bạn sẽ không thể CƯU mang hay thực hiện một cách hoàn chỉnh hay trọn vẹn được, do đó gặp phải thất bại. Bạn nên đánh giá những ưu điểm và khuyết điểm của mình, và chọn ra đường hướng hành động thích hợp, khi đó, vận may của bạn sẽ thay đổi. Bạn có thể bị lôi kéo vào những phiền phức, rắc rối và tâm trí của bạn rối tung và lúng túng. Hoặc bạn có thể trở thành nạn nhân của lỗi lầm nào đó trong sự dẫn chứng bằng tư liệu, hoặc bị lũ lụt. Hành động hấp tấp và mù quáng sẽ khiến bạn gặp thất bại.</p>
