    <li>Con cái: Đông con. Việc nuôi dưỡng sê khó khăn. Có sự thiếu hiểu biết và tha thứ giữa cha mẹ và con cái. Phải kiên trì trong việc dạy bảo và dẫn dắt chúng. Có như vậy, hạnh phúc và may mắn sẽ thuộc về bạn. Thai nghén: con trai.</li>
