        name: "Đỉnh", // Hỏa Phong Đỉnh
        detail: `
<h2>Quẻ: Đỉnh</h2>
<p>Quẻ Đỉnh chỉ thời vận tốt, mọi việc hanh thông, cơ hội vững vàng. Trước mắt có thể chưa thuận lợi nhưng tương lai có nhiều cơ hội tốt, có quý nhân phò trợ. Công danh sự nghiệp thành đạt nhất là tìm được bạn đồng hành hoặc tìm được người đỡ đầu có thế lực. Thời vận khá, lương thực dồi dào, kinh doanh phát đạt. Sĩ tử dễ đỗ cao, tìm việc dễ, xuất hành tốt. Bệnh tật nên tìm thầy, thuốc cẩn thận. Kiện tụng dây dưa nhưng cuối cùng sẽ thắng. Tình yêu khó khăn lúc đầu, sau thuận lợi. Hôn nhân dễ thành lương duyên. Người có quẻ này sinh tháng 12 là đắc cách, sự nghiệp hiển vinh, phúc lộc dồi dào.</p>

<p><strong>Đạo của người quân tử:</strong></p>
<p>Quẻ Đỉnh, Tự quái nói rằng: Thay đổi các vật, không gì bằng cái vạc, cho nên tiếp đến quẻ Đỉnh. Sự dùng của cái vạc, là để thay đổi các vật, biến thứ sống ra thứ chín, đổi cái rắn thành cái mềm.</p>

<p><strong>Điểm xấu:</strong></p>
<ul>
    <li>Chui rèn nhiều mới thành công à mơ mộng nhiều, muốn ở trên cao à có cái tôi lớn, nghĩ rằng mình trên người ta.</li>
    <li>Muốn trở thành người nói được làm được, nhất ngôn cửu đỉnh nhưng thực tế lại không được, xảy ra ngoài ý muốn</li>
    <li>Dễ tự mãn nếu không giữ khiêm tốn.</li>
    <li>Nhà có ánh sáng mạnh, cần cân bằng phong thủy.</li>
</ul>

<p><strong>Phong thủy:</strong></p>
<p></p>

<p><strong>Tháng tốt:</strong> 12</p>
<p><strong>Đoán quẻ 1:</strong></p>
<p>Ngoại là Dụng Ly Hỏa được Thể Tốn Mộc sinh là sự cùng cực của chi phí đến lúc không thể thêm được nữa là khi sự thành công không được đánh giá đúng mức. Hào quẻ hiện nhiều Tử tôn và Thê tài là nguồn lợi tự mình làm ra khá lớn. Nếu trông chờ thì sự xấu là triền miên. Đây là quẻ của người trí dũng song toàn. Đã đến lúc được đánh giá qua thời gian thử thách.</p>
<ul>
    <li>Tình thế hiện tại : Đang dần tốt lên do về trên đề bạt, hoặc do tự mình thay đổi cách thức. Lấy sự học làm đầu thì sẽ được trọng dụng.</li>
    <li>Tương lai : Thoạt đầu tưởng khó thực hiện, nhưng nếu nhờ bề trên thì có thể thành công. Bỏ ra nhiều công sức về sau mới có kết quả tốt.</li>
    <li>Sự nghiệp : Hiển đạt. Nếu có học sẽ rực rõ nhưng khá thăng trầm. Muốn về vững phải liên tục mở cái mới để phù hợp với thời đại.</li>
    <li>Nghề nghiệp : Đổi nghề sẽ gặp khó khăn vất vả lúc ban đầu, đổi nhiều thì tốt lên.</li>
    <li>Học tập &amp; thi cử : Kết quả tốt do có động cơ và định hướng đúng trong học tập</li>
    <li>Tiền tài- của cải : Bình thường. Chữ tài đi với chữ tai, lợi ít hại nhiều. Hay để lại hậu quả và vấn đề tiền bạc.</li>
    <li>Tình duyên- hôn nhân : Có thể thành lương duyên. Nếu mới gặp đi đến kết hôn nhân ngay thì tốt. Để lâu sẽ bất lợi, chia tay.</li>
    <li>Sinh con&amp;Cầu con : Như ý, có trai có gái.</li>
    <li>Bệnh tật : Nên đổi phương thuốc sẽ hiệu quả. Phòng hen suyễn, bệnh phổi, đường hô hấp</li>
    <li>Xuất hành : Chuyến đi chơi thú vị, Lợi phương Bắc, Đông nhưng đi mau về mau thì tốt , kéo dài không hay</li>
    <li>Mất của &amp; Chi phí : Có thể tìm thấy hoặc do chi ra nhưng sau đó thu lại được rất nhiều.</li>
    <li>Tranh chấp và mâu thuẫn : Mất thời gian nhưng thắng kiện</li>
    <li>Mồ mả : Rất tốt. Khu mộ quay đầu về hướng bắc, Đông thì gia đình được phát phúc nhanh. Tây và Nam thì gia đình nghèo túng.</li>
    <li>Nhà cửa: AN lành. Nhà cửa tuổi Tây tứ trạch thì được may mắn, Đông tứ trạch thì nghèo túng.</li>
    <li>Sự việc : Luôn phải đầu tư mua thì có lợi, Bán ra thì chịu thiệt thòi mà vẫn bất lợi. Học nghề thì tốt, học văn hóa thì bỏ học giữa chừng</li>
</ul>
<p><strong>Đoán quẻ 2:</strong> Vận may an toàn, phong phú và không bị cản trở. Cấp trên có thể đang quan tâm đến bạn và giúp bạn phát huy hết tài năng của mình. Các đầu tư hợp tác thì cát tường.</p>
<ul>
    <li>Ước muốn: Sẽ thực hiện được mục tiêu.</li>
    <li>Hôn nhân: Một cuộc hôn nhân tương xứng, may mắn và thịnh vượng. Thành công là rõ rệt. Người thứ ba có thể xuất hiện – tình nhân, mẹ vợ hay mẹ chồng hoặc ai đó – nhưng cuộc hôn nhân vẫn sẽ đạt kết quả hòa hợp và thật đáng hài lòng.</li>
    <li>Tình yêu: Nhất định thành công.</li>
    <li>Gia đạo: Cơ đồ của gia đình đã sung thịnh rồi và thậm chí sẽ càng trở nên sung thịnh hơn nữa.</li>
    <li>Con cái: Con cái được ban cho tài năng xuất sắc. Chúng sẽ thành công trong tương lai. Thai nghén: con gái.</li>
    <li>Vay vốn: Thành công.</li>
    <li>Kinh doanh: Lợi nhuận rất cao.</li>
    <li>Thị trường chứng khoán: ổn định và thuận lợi.</li>
    <li>Tuổi thọ: Khỏe mạnh, sống thọ.</li>
    <li>Bệnh tật: Sớm bình phục. Những bệnh liên quan đến cơ quan tiêu hóa, bệnh tiểu đường.</li>
    <li>Chờ người: Sẽ đến.</li>
    <li>Tìm người: Sẽ sớm tìm được người này, hoặc họ sẽ sớm tự động trở về. Hãy tìm ở hướng đông nam hoặc hướng nam.</li>
    <li>Vật bị mất: Có thể tìm thấy. Hãy tìm ở hướng đông nam hoặc hướng nam.</li>
    <li>Du lịch: Hết sức cát tường.</li>
    <li>Kiện tụng và tranh chấp: Thắng lợi.</li>
    <li>Việc làm: Thuận lợi.</li>
    <li>Thi cử: Điểm rất cao.</li>
    <li>Kinh doanh mới, thay đổi nghề nghiệp, chuyên môn hay chỗ làm: Hết sức tốt đẹp.</li>
    <li>Thời tiết: Thời tiết tuyệt đẹp, có gió nhẹ.</li>
    <li>Thế vận: đang tốt lên, sự nỗ lực của bản thân hoặc sự giúp đỡ của người khác có hiệu quả.</li>
    <li>Hy vọng: lúc đầu tưởng khó thành, song có sự giúp đỡ của người khác có thể thành công.</li>
    <li>Tài lộc: bình thường.</li>
    <li>Sự nghiệp: hiện khó khăn, sau phát triển mạnh.</li>
    <li>Nhậm chức: nhờ bạn mà có địa vị tốt.</li>
    <li>Nghề nghiệp: đổi nghề sẽ gặp nhiều khó khăn.</li>
    <li>Tình yêu: đối tượng đang còn lựa chọn.</li>
    <li>Hôn nhân: có thể thành lương duyên.</li>
    <li>Đợi người: sắp đến.</li>
    <li>Đi xa: chuyến đi thú vị</li>
    <li>Pháp lý: thời gian kéo dài, nhưng thắng kiện.</li>
    <li>Sự việc: việc giải quyết được khi có người trung gian.</li>
    <li>Bệnh tật: đổi hướng điều trị bệnh sẽ khỏi.</li>
    <li>Xem thi cử: kết quả tốt</li>
    <li>Mất của: có thể thấy.</li>
    <li>Xem người ra đi: có thể tìm được nơi người bỏ đi.</li>
</ul>
`
