    <li>Bệnh tật: Nghiêm trọng, nhưng có thể bình phục nhờ tịnh dưỡng. Bệnh thiếu máu, các bệnh liên quan đến các cơ quan tiêu hóa, nói chung yếu đuối, dễ bệnh hoạn.</li>
