<p><strong>Đoán quẻ 2:</strong> Những hành động hấp tấp sẽ dẫn đến thất bại. Phải giữ vững con đường chính đáng của mình, vun bồi nhân cách và khả năng dể đạt được thành công. Những lời nói và hành vi bất cẩn có thể mang đến điều không may. Bệnh tật có thể đến từ sự thiếu chăm sóc sức khỏe đúng đắn. Những người bên dưới có thể lôi kéo bạn liên can vào việc gì đó. Những đầu tưhợp tác thì thuận lợi và khả quan hơn những đầu tư một mình.</p>
