        detail: `
<h2>Quẻ: Cổ</h2>
<p>Quẻ Cổ chỉ thời vận tương đối khó khăn trắc trở, ít có cơ hội thành đạt cần phải chờ thời thế đổi thay. Sự nghiệp công danh khó thành. Tài vận, kinh doanh ít thuận lợi. Xuất hành bất lợi, dễ hao tài tốn của. Thi cử khó đạt. Tình yêu không ổn định, đứng núi này trông núi nọ. Người gặp quẻ này, sinh vào tháng giêng là gặp các công danh phú quý. Tuy nhiên đối với gia đình, cha mẹ thường kém hòa thuận.</p>

<p><strong>Đạo của người quân tử:</strong></p>
<p>Cổ là nát hỏng đến cực điểm mà phải có việc. Quẻ có Cấn cứng ở trên, T ôn mềm ở dưới, trên dưới không giao với nhau, dưới mềm nhún mà trên cẩu thả dừng đậu, cho nên là cổ.</p>

<p><strong>Điểm xấu:</strong></p>
<ul>
    <li>Biến cố, hư hỏng, nhà có " bạn"</li>
    <li>Thời vận chưa ổn, cần cải tổ mọi mặt.</li>
    <li>Nhà có gió lùa, phong thủy bất lợi.</li>
    <li>Tài vận chưa ổn, thi cử bình thường, xuất hành trở ngại.</li>
    <li>Bệnh tật kéo dài, tình yêu khó khăn.</li>
</ul>

<p><strong>Phong thủy:</strong></p>
<p></p>

<p><strong>Tháng tốt:</strong> 1</p>
<p><strong>Đoán quẻ 1:</strong></p>
<p>Sơn Phong Cổ có Ngoại Cấn Dụng bị nội Tốn Mộc Thể khắc chế, việc chậm do nội lấn ngoại. Dù có sẵn tài nhưng hãy thận trọng, cần xem xét v lắng nghe ý kiến người khác, liệu cơm gắp mắm đừng tính cua trong lỗ thì sẽ thuận lợi.</p>
<ul>
    <li>Tình thế hiện tại: Vốn bình thường, do chủ quan sơ xuất mà lâm vào tình thế nguy hiểm. Phải thay đổi ngay sách lược thì sẽ trở lại bình thường. Vì quá tự tin vào khả năng mà bị mất tiền</li>
    <li>Tương lai: Tưởng chừng dễ thực hiện, song thực ra có nhiều trở ngại, khó thực hiện do chủ quan.</li>
    <li>Sự nghiệp: Không có vì nhiều trở ngại do ko có thực lực.</li>
    <li>Nghề nghiệp: Sau khi chuyển nghề tạm thời sút kém, sau mới tốt.</li>
    <li>Học tập thi cử: Không đạt do trình độ thấp. Học lại thì hơn.</li>
    <li>Tiền tài của cải: Không có nhiều vì tưởng nguồn thu là đương nhiên. DO chủ quan mà nguồn tiền bị đảo ngược.</li>
    <li>Tình duyên- hôn nhân Không thành do 2 bên che dấu sự thật, đến khi hôn nhân mới vỡ lở chia tay.</li>
    <li>Sinh con- cầu con: Có trai có gái nhưng phải chú ý dạy đạo đức ngay từ nhỏ vì nghiệp chướng của gia đình.</li>
    <li>Bệnh tật: Dây dưa lâu khỏi. Đừng chủ quan cho là bệnh nhẹ. VÌ không rõ bệnh nên hãy lạc quan bệnh sẽ hết.</li>
    <li>Xuất hành: Có trở ngại, nên bỏ ý định. Lợi phương Đông, hướng Bắc tốt, còn lại là xấu</li>
    <li>Mất của- chi phí: Bị đè dưới vật khác, đã biến dạng, hay chi tiếu quá mức nên tưởng là mất.</li>
    <li>Tranh chấp – mâu thuẫn: Nên hòa giải vì phía dưới mình chưa đủ bằng cớ v lý lẽ.</li>
    <li>Mồ mả: Bình an, đang tốt đẹp đừng xây sửa. Nếu cứ muốn xây sửa thì sẽ từ tốt thành xấu, phải thận trọng.</li>
    <li>Nhà cửa: Yên lành, đừng vì sĩ diện theo hàng xóm vay tiền xây sửa lại xấu thêm + nợ nần. Không có khả năng trả.</li>
</ul>
<p><strong>Đoán quẻ 2:</strong> Mọi việc đều ngừng trệ và ách tắc; nhiều loại khó khăn và trở ngại xuất hiện. Cùng lúc đó, bạn phải lo toan cho gia đình. Việc gia đình của bạn có thể cũng đang rối loạn và xáo trộn. Cũng có thể có những vướng mắc của tình yêu bất chính và bệnh tật.</p>
<ul>
    <li>Ước muốn: Không thành công. Hãy thay đổi cách làm và cố gắng lần nữa.</li>
    <li>Hôn nhân: Cả hai bên thiếu duyên phận, không xứng hợp với nhau, và nhiều vấn nạn. Tốt nhất hãy từ bỏ cuộc hôn nhân này.</li>
    <li>Tình yêu: Đã thân mật nhưng có nhiều rắc rối và đau khổ. Tốt nhất hãy kết thúc ngay các quan hệ.</li>
    <li>Gia đạo: Gia đạo thật rối rắm, nhiều phiền toái, bực mình. Phải tề gia bằng quyết tâm, nếu không có thể xảy ra cảnh gia đình tan nát và chia ly.</li>
    <li>Con cái: Con cái kém hạnh. Bởi chúng tạo ra rắc rối không ngừng, nên việc lo rầu về chúng sẽ khiến bạn hết sức đau khổ. Phải hết sức nghiêm khắc trong việc dạy dỗ và chỉ bảo chúng; bằng không, kết quả sẽ thật không thể tưởng tượng nổi. Thai nghén: con trai.</li>
    <li>Vay vốn: Không thành công.</li>
    <li>Kinh doanh: Có vẻ hàng hóa đã được tồn trữ và bày biện rồi nhưng không thể bán được.</li>
    <li>Tuổi thọ: Bệnh tật và yếu đuối – thậm chí có khả năng đoản thọ. Phải hết sức chú ý đến việc chăm sóc sức khỏe.</li>
    <li>Thị trường chứng khoán: Giá cả đang lúc giảm mạnh.</li>
    <li>Bệnh tật: Nghiêm trọng, thậm chí có thể phải cần đến phẫu thuật hay cách chữa trị đặc biệt. Những bệnh liên quan đến dạ dày hay vùng bụng.</li>
    <li>Chờ người: Điều gì đó đã xảy ra trên đường, và người đó sẽ không đến.</li>
    <li>Tìm người: Người này đã bỏ đi vì sự bất hòa trong gia đình hay do cách xử sự không đúng. Hãy tìm ở hướng đông bắc hay đông nam.</li>
    <li>Vật bị mất: Đang nằm bên dưới vật gì đó hay dưới đáy một cái hộp. Hãy tìm ở hướng đông bắc hoặc đông nam.</li>
    <li>Du lịch: Khó khăn dọc trên đường. Tốt nhất là nên từ bỏ kế hoạch.</li>
    <li>Kiện tụng và tranh chấp: Mất nhiều thời gian và kéo dài. Không dễ gì giải quyết được. Tốt nhất hãy thay đổi chiến thuật hoặc cách làm để giành được kết thúc có lợi.</li>
    <li>Việc làm: Sẽ thất bại vào lúc này.</li>
    <li>Thi cử: Điểm rất thấp.</li>
    <li>Kinh doanh mới, thay đổi nghề nghiệp, chuyên môn hay chỗ làm: Cát tường, nhưng phải chọn cách hành động mới.</li>
    <li>Thời tiết: Nhiều mây và nhiều gió.</li>
    <li>Thế vận: hiện bình thường. Do chủ quan mà lâm vào tình thế nguy hiểm. Thay đổi cách ứng xử sẽ trở lại bình thường.</li>
    <li>Hy vọng: có nhiều trở ngại, khó đạt.</li>
    <li>Tài lộc: chưa có</li>
    <li>Sự nghiệp: dễ đổ vỡ, nên tạm dừng.</li>
    <li>Nhậm chức: có trở ngại, khó như ý</li>
    <li>Nghề nghiệp: sau khi chuyển nghề tạm thời sút kém rồi sau chuyển biến tốt.</li>
    <li>Tình yêu: đối tượng chưa gắn bó, còn đắn đo.</li>
    <li>Hôn nhân: không thành.</li>
    <li>Đợi người: họ chưa đến, phải chờ lâu.</li>
    <li>Đi xa: nên bỏ ý định vì sẽ có trở ngại.</li>
    <li>Pháp lý: nên hòa giải.</li>
    <li>Sự việc: giải quyết ngay thì ổn, kéo dài bất lợi.</li>
    <li>Bệnh tật: lâu khỏi.</li>
    <li>Thi cử: không đạt</li>
    <li>Mất của: bị che lấp, bị biến dạng.</li>
    <li>Xem người ra đi: ra đi không biết nương vào đâu.</li>
</ul>
`
